<script setup lang="ts">
import {computed} from 'vue';import {Users,MessagesSquare,Inbox,ArrowDownLeft,ArrowUpRight,ArrowRight,Activity,Workflow} from 'lucide-vue-next';import {useSession} from '../stores/session';import {useWorkspace} from '../stores/workspace';import Avatar from '../components/Avatar.vue';import Channel from '../components/Channel.vue';import Notice from '../components/Notice.vue';import {time} from '../utils/format'
const s=useSession(),w=useWorkspace();const demo=computed(()=>s.mode==='demo');const stats=computed(()=>[{label:'Clientes registrados',value:demo.value?w.customers.length:w.stats?.customers??'—',icon:Users,note:'En tu espacio de trabajo'},{label:'Conversaciones',value:demo.value?w.conversations.length:w.stats?.conversations??'—',icon:MessagesSquare,note:'Todos los canales'},{label:'Conversaciones abiertas',value:demo.value?w.conversations.filter(c=>c.status==='open').length:w.stats?.open_conversations??'—',icon:Inbox,note:'Pendientes de atención'},{label:'Mensajes recibidos',value:demo.value?w.messages.filter(m=>m.direction==='inbound').length:w.stats?.inbound_messages??'—',icon:ArrowDownLeft,note:'Entrantes'},{label:'Mensajes enviados',value:demo.value?w.messages.filter(m=>m.direction==='outbound').length:w.stats?.outbound_messages??'—',icon:ArrowUpRight,note:'Salientes registrados'}]);const recent=computed(()=>[...w.messages].sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,4));const channelCounts=computed(()=>['whatsapp','instagram','messenger','web'].map(channel=>({channel,count:w.conversations.filter(c=>c.channel===channel).length})))
</script>
<template><div class="page-heading"><div><div class="eyebrow">TU CENTRO DE OPERACIONES</div><h1>Todo conectado. Todo bajo control<span class="teal-text">.</span></h1><p>Una mirada a las conversaciones que acercan a tu equipo y tus clientes.</p></div><RouterLink to="/conversations" class="button primary"><MessagesSquare :size="17"/> Ir a conversaciones <ArrowUpRight :size="16"/></RouterLink></div>
<Notice v-if="demo">Estás explorando una demostración. Las métricas, los canales y la actividad son datos de ejemplo.</Notice><Notice v-else>Estadísticas sincronizadas con PostgreSQL. Los mensajes enviados corresponden a registros del sistema, no necesariamente a entregas externas.</Notice><Notice v-if="w.error" error>{{w.error}} <button class="text-button" @click="w.load">Reintentar</button></Notice>
<div v-if="w.loading" class="loading" role="status">Cargando tu espacio de trabajo…</div><template v-else><div class="stats-grid"><article class="stat-card" v-for="stat in stats" :key="stat.label"><div><span>{{stat.label}}</span><component :is="stat.icon" :size="18"/></div><strong>{{w.error?'—':stat.value}}</strong><small>{{stat.note}}</small></article></div>
<div class="dashboard-grid"><section class="card activity-chart"><div class="card-heading"><div><h2>El pulso de tus conversaciones</h2><p>{{demo?'Distribución de los mensajes de ejemplo':'Actividad pendiente de API de estadísticas'}}</p></div><span class="chip">{{demo?'Muestra ilustrativa':'Sin datos'}}</span></div><div v-if="demo" class="chart" role="img" aria-label="Gráfico ilustrativo de actividad, sin métricas reales"><div class="chart-grid"><span>24</span><span>18</span><span>12</span><span>6</span><span>0</span></div><svg viewBox="0 0 800 190" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#17a398" stop-opacity=".18"/><stop offset="100%" stop-color="#17a398" stop-opacity="0"/></linearGradient></defs><path d="M0 155 C50 155 50 110 110 120 S190 160 240 100 S310 105 355 80 S430 130 480 65 S550 80 600 35 S710 75 800 15 L800 190 L0 190Z" fill="url(#fill)"/><path d="M0 155 C50 155 50 110 110 120 S190 160 240 100 S310 105 355 80 S430 130 480 65 S550 80 600 35 S710 75 800 15" fill="none" stroke="#159e94" stroke-width="3"/><path d="M0 175 C60 175 70 155 120 160 S200 140 250 150 S330 110 380 130 S450 100 500 115 S570 80 620 100 S730 70 800 80" fill="none" stroke="#94aabc" stroke-width="2" stroke-dasharray="6 5"/></svg><div class="chart-days"><span v-for="day in ['Lun','Mar','Mié','Jue','Vie','Sáb','Dom']" :key="day">{{day}}</span></div></div><div v-else class="empty"><Activity/><p>Aquí verás la actividad de tu organización.</p></div><div class="chart-legend"><span><i class="legend-dot teal"></i>Recibidos</span><span><i class="legend-dot gray"></i>Enviados</span><small>{{demo?'Visualización de ejemplo':'No disponible'}}</small></div></section>
<section class="card channels-card"><div class="card-heading"><div><h2>Cada canal, un solo lugar</h2><p>{{demo?'Conversaciones de demostración':'Distribución real de conversaciones'}}</p></div></div><div v-for="item in channelCounts" :key="item.channel" class="channel-row"><Channel :channel="item.channel"/><div class="channel-bar"><span :style="{width:(item.count/Math.max(1,w.conversations.length)*100)+'%'}"></span></div><strong>{{item.count}}</strong></div><small class="caption">Los canales mostrados no confirman integraciones operativas.</small></section>
<section class="card recent-card"><div class="card-heading"><div><h2>Conversaciones recientes</h2><p>Las personas detrás de cada mensaje.</p></div><RouterLink to="/conversations" class="text-link">Ver conversaciones <ArrowRight :size="15"/></RouterLink></div><div class="table-scroll"><table><thead><tr><th>CLIENTE</th><th>CANAL</th><th>ÚLTIMO MENSAJE</th><th>ESTADO</th></tr></thead><tbody><tr v-for="c in w.conversations.slice(0,4)" :key="c.id"><td><RouterLink :to="`/conversations?id=${c.id}`" class="person"><Avatar :name="w.customers.find(x=>x.id===c.customer_id)?.name||'Cliente'" :index="c.customer_id"/><strong>{{w.customers.find(x=>x.id===c.customer_id)?.name||'Cliente'}}</strong></RouterLink></td><td><Channel :channel="c.channel"/></td><td class="muted truncate-cell">{{w.messages.filter(m=>m.conversation_id===c.id).at(-1)?.content||c.last_message||'Sin mensajes'}}</td><td><span class="status" :class="c.status">{{c.status==='open'?'Abierta':'Cerrada'}}</span></td></tr></tbody></table></div><div v-if="!w.conversations.length" class="empty">Todavía no hay conversaciones registradas en tu organización.</div></section>
<section class="card recent-activity"><div class="card-heading"><div><h2>Actividad reciente</h2><p>{{demo?'Lo que sucede en tu espacio de ejemplo':'Pendiente de API de actividad'}}</p></div><Activity :size="18"/></div><div v-for="m in recent" :key="m.id" class="activity-row"><span class="activity-icon"><component :is="m.direction==='inbound'?ArrowDownLeft:ArrowUpRight" :size="16"/></span><div><strong>{{m.direction==='inbound'?'Nuevo mensaje recibido':'Respuesta registrada'}}</strong><p>Conversación #{{m.conversation_id}} <span>· {{time(m.created_at)}}</span></p></div></div><div v-if="!recent.length" class="empty">No hay actividad disponible.</div><RouterLink to="/automations" class="automation-link"><Workflow :size="18"/><span>Conoce el flujo de automatización</span><ArrowRight :size="16"/></RouterLink></section></div></template></template>
